from google import genai
client = genai.Client()
tools = [
  {"type": "tool_search"},
  {
    "type": "function",
    "name": "issue_refund",
    "description": "将订单退款至原始支付方式。",
    "defer_loading": True,
    "parameters": {
      "type": "object",
      "properties": {
        "order_id": {"type": "string"},
        "amount": {"type": "number"},
      },
      "required": ["order_id", "amount"],
    },
  },
  # ... 50 多个其他延迟函数（常用工具保持不延迟）
]
interaction = client.interactions.create(
  model="gemini-4-hydrogen",
  input="订单 A-1042 送达时已损坏。请退款 40 美元。",
  tools=tools,
)

